// Formata o payload de incidente da DLQ do FastAPI em alerta Markdown com UUID e Stack Trace
const body = $input.first().json.body || $input.first().json;

const traceId = body.trace_id || 'sem-uuid';
const rota = body.rota || 'N/D';
const servico = body.servico || 'N/D';
const tipoErro = body.tipo_erro || 'ErroAplicacao';
const erro = body.erro || 'Falha interna não especificada';
const timestamp = body.timestamp || new Date().toISOString();
const stackBruto = String(body.stack_trace || 'Stack trace não disponível').slice(0, 1200);

const markdown = [
  '🚨 *ALERTA DE INCIDENTE — DLQ (Guia do Turista Inteligente V3)*',
  '',
  `🆔 *UUID de Rastreio:* \`${traceId}\``,
  `🛣️ *Rota:* \`${rota}\``,
  `⚙️ *Serviço:* \`${servico}\` (*${tipoErro}*)`,
  `🕒 *Horário (UTC):* \`${timestamp}\``,
  `⚠️ *Mensagem:* ${erro}`,
  '',
  '📋 *Stack Trace:*',
  '```python',
  stackBruto,
  '```'
].join('\n');

return [
  {
    json: {
      trace_id: traceId,
      rota,
      servico,
      markdown_alerta: markdown,
      chat_id: $env.TELEGRAM_SUPPORT_CHAT_ID || ''
    }
  }
];
